// @options: { "timeout_ms": 60000 }

// 1. Get file list
const bashRes = await tools.bash({ command: "find src -name '*.js' | sort && echo --- && ls config" });
const out = typeof bashRes === "string" ? bashRes : bashRes.output;
const [srcPart, cfgPart] = out.split("---");
const srcFiles = srcPart.split("\n").map(s => s.trim()).filter(Boolean);
const cfgFiles = cfgPart.split("\n").map(s => s.trim()).filter(s => s.endsWith(".json")).map(s => "config/" + s);
console.log("src files:", srcFiles.join(", "));
console.log("config files:", cfgFiles.join(", "));

// 2. Read all sources at once
const reads = await Promise.all(srcFiles.map(f => tools.read({ path: f, offset: 1, limit: 500 })));
const sources = {}; // path -> text
await Promise.all(srcFiles.map(async (f, i) => { sources[f] = reads[i]; }));

// 3. Find enclosing function of each legacyLog( call via brace-stack scan
const KEYWORDS = new Set(["if","for","while","switch","catch","return","else","do","try","function","typeof","new","delete","void","in","of"]);
function enclosingFunctions(text) {
  const results = [];
  const tokens = []; // ordered {type:'sig',name,idx} | {type:'{',idx} | {type:'}',idx} | {type:'call',idx}
  const sigRe = /((?:function\s+([A-Za-z0-9_$]+))|((?:const|let|var)\s+([A-Za-z0-9_$]+)\s*=\s*(?:async\s*)?(?:\([^)]*\)|[A-Za-z0-9_$]+)\s*=>)|((?:async\s+)?([A-Za-z0-9_$]+)\s*\([^)]*\)\s*\{)|([A-Za-z0-9_$]+)\s*:\s*(?:async\s*)?function)|legacyLog\s*\(|\{|\}/g;
  let m;
  while ((m = sigRe.exec(text)) !== null) {
    if (m[0] === "legacyLog(" || m[0].startsWith("legacyLog")) { tokens.push({ type: "call", idx: m.index }); continue; }
    if (m[0] === "{") { tokens.push({ type: "{", idx: m.index }); continue; }
    if (m[0] === "}") { tokens.push({ type: "}", idx: m.index }); continue; }
    const name = m[2] || m[4] || m[6] || m[8] || "<anonymous>";
    if (KEYWORDS.has(name)) { tokens.push({ type: "{", idx: m.index }); continue; } // keyword blocks like if(...){
    tokens.push({ type: "sig", name, idx: m.index });
  }
  const stack = []; let pending = null;
  for (const t of tokens) {
    if (t.type === "sig") pending = t.name;
    else if (t.type === "{") { stack.push(pending ?? "<block>"); pending = null; }
    else if (t.type === "}") { stack.pop(); pending = null; }
    else if (t.type === "call") {
      // nearest named frame
      let fn = null;
      for (let i = stack.length - 1; i >= 0; i--) if (stack[i] && stack[i] !== "<block>") { fn = stack[i]; break; }
      results.push({ idx: t.idx, fn: fn ?? "<module>" });
    }
  }
  return results;
}

let total = 0; const callers = [];
for (const f of srcFiles) {
  if (f === "src/lib/log.js") {
    // definition file: count only call sites, not the export definition
  }
  const hits = enclosingFunctions(sources[f]);
  for (const h of hits) {
    total++;
    const line = sources[f].slice(0, h.idx).split("\n").length;
    callers.push(`${f}:${h.fn} (line ${line})`);
  }
}
console.log("\nlegacyLog( call sites:");
callers.forEach(c => console.log("  " + c));
console.log("TOTAL call sites:", total);

// Exclude the definition itself (in src/lib/log.js the regex matches the definition line "export function legacyLog(level, msg) {")
// Check what hit occurred there:
console.log("\nlog.js content:", JSON.stringify(sources["src/lib/log.js"]));

// 4. Config keys vs usage
const allText = srcFiles.map(f => sources[f]).join("\n");
const cfgReads = await Promise.all(cfgFiles.map(f => tools.read({ path: f, offset: 1, limit: 200 })));
const keyReport = [];
cfgFiles.forEach((cf, i) => {
  const keys = Object.keys(JSON.parse(cfgReads[i]));
  for (const k of keys) keyReport.push(`${k} (${cf}): ${allText.includes(k) ? "USED" : "UNUSED"}`);
});
console.log("\nconfig keys:");
keyReport.forEach(k => console.log("  " + k));
return "done";
